<script lang="ts">
  import type {AppData,Row} from '#lib/client/types.ts';import {display} from '#lib/client/api.ts';import Status from './Status.svelte';import TimeSnapshot from './TimeSnapshot.svelte';import Icon from './Icon.svelte';
  let {data,day,oncorrect}:{data:AppData;day:string;oncorrect:(session:Row)=>void}=$props();
  function businessDate(value:any){const date=new Date(value);return Number.isFinite(date.getTime())?new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin'}).format(date):'';}
  const sessions=$derived((data.related?.time_sessions||[]).filter(s=>businessDate(s.started_at)===day));
  function corrections(sessionId:string){return (data.related?.time_corrections||[]).filter(c=>c.session_id===sessionId);}
</script>
{#if sessions.length}<section class="panel"><header class="panel-header"><div><h2>Meine erfassten Sitzungen</h2><p>Originalaufzeichnungen bleiben erhalten. Korrekturen werden mit Begründung von einer anderen Person geprüft.</p></div></header><div class="panel-body">{#each sessions as session}<article class="session-history"><div class="session-summary"><div><h3>{display(session.started_at,'started_at')} – {session.ended_at?display(session.ended_at,'ended_at'):'läuft'}</h3><div class="inline-actions"><Status value={session.status}/><span class="field-help">Version {session.version}</span></div></div><button class="btn small" disabled={!session.ended_at||session.status==='submitted'} onclick={()=>oncorrect(session)}><Icon name="edit" size={15}/>Korrektur beantragen</button></div>{#if session.status==='submitted'}<p class="field-help mt">Dieser Stand ist zur Prüfung eingereicht. Bei einer Änderung muss die zuständige Person die Abgabe zuerst mit einer Rückfrage zurückgeben.</p>{/if}<details class="mt"><summary>Unveränderte Originalaufzeichnungen ansehen</summary><div class="mt"><TimeSnapshot snapshot={{session,segments:(data.related.time_segments||[]).filter(s=>s.time_session_id===session.id),allocations:(data.related.time_allocations||[]).filter(a=>a.time_session_id===session.id)}} {data}/></div></details>{#each corrections(session.id) as correction}<details class="mt"><summary><Status value={correction.status}/><span>Korrekturantrag · {correction.reason}</span></summary><div class="mt"><TimeSnapshot snapshot={correction.new_snapshot} {data}/></div></details>{/each}</article>{/each}</div></section>{/if}
<style>.session-history+.session-history{border-top:1px solid var(--line);padding-top:22px;margin-top:22px}.session-summary{display:flex;align-items:flex-start;justify-content:space-between;gap:18px}.session-summary h3{font-size:14px;font-weight:500;margin-bottom:9px}.session-history summary{display:flex;align-items:flex-start;gap:9px;cursor:pointer;font-size:13px;line-height:1.7}@media(max-width:760px){.session-summary{flex-direction:column}.session-summary .btn{width:100%}}</style>
